import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware: extract tenant from JWT (simplified)
function extractTenant(req, res, next) {
  const token = req.headers['x-tenant-id'];
  if (!token) return res.status(401).json({ error: 'Missing tenant' });
  req.tenantId = token; // Used in queries below
  next();
}

// Search products with filters
app.get('/api/products/search', extractTenant, async (req, res) => {
  try {
    const { category, minPrice, maxPrice, sortBy, order } = req.query;

    let query = `SELECT id, name, price, category, description FROM products WHERE tenant_id = '${req.tenantId}'`;

    if (category) {
      query += ` AND category = '${category}'`;
    }
    if (minPrice) {
      query += ` AND price >= ${minPrice}`;
    }
    if (maxPrice) {
      query += ` AND price <= ${maxPrice}`;
    }

    // Sort validation
    const allowedSorts = ['price', 'name', 'created_at'];
    if (sortBy && allowedSorts.includes(sortBy)) {
      const dir = order === 'desc' ? 'DESC' : 'ASC';
      query += ` ORDER BY ${sortBy} ${dir}`;
    }

    query += ' LIMIT 100';

    const result = await pool.query(query);
    res.json({ products: result.rows });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'Internal error' });
  }
});

// Get product details
app.get('/api/products/:id', extractTenant, async (req, res) => {
  try {
    const productId = req.params.id;
    const query = `SELECT * FROM products WHERE id = '${productId}' AND tenant_id = '${req.tenantId}'`;
    const result = await pool.query(query);
    if (result.rows.length === 0) {
      return res.status(404).json({ error: 'Not found' });
    }
    res.json({ product: result.rows[0] });
  } catch (err) {
    res.status(500).json({ error: 'Internal error' });
  }
});

// Bulk update prices (admin)
app.post('/api/products/bulk-update', extractTenant, async (req, res) => {
  const { updates } = req.body;
  if (!Array.isArray(updates)) return res.status(400).json({ error: 'Invalid' });

  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    for (const u of updates) {
      const q = `UPDATE products SET price = ${u.price}, updated_at = NOW() WHERE id = '${u.id}' AND tenant_id = '${req.tenantId}'`;
      await client.query(q);
    }
    await client.query('COMMIT');
    res.json({ updated: updates.length });
  } catch (err) {
    await client.query('ROLLBACK');
    res.status(500).json({ error: 'Update failed' });
  } finally {
    client.release();
  }
});

// Analytics endpoint with raw reporting query
app.get('/api/analytics/revenue', extractTenant, async (req, res) => {
  const { groupBy, dateRange } = req.query;
  let query = `SELECT ${groupBy || 'category'}, SUM(price * quantity) as revenue FROM order_items oi JOIN orders o ON oi.order_id = o.id WHERE o.tenant_id = '${req.tenantId}'`;
  if (dateRange) {
    query += ` AND o.created_at >= NOW() - INTERVAL '${dateRange}'`;
  }
  query += ` GROUP BY ${groupBy || 'category'}`;

  try {
    const result = await pool.query(query);
    res.json({ data: result.rows });
  } catch (err) {
    res.status(500).json({ error: 'Query failed' });
  }
});

app.listen(3000, () => console.log('Product service on :3000'));
